const teamCompanies = `-- name: TeamCompanies :many
SELECT t.company_id, l.n AS active_load
FROM (
    SELECT c.company_id FROM companies AS c WHERE c.team_active
    UNION
    SELECT cv.company_id FROM conversations AS cv
    WHERE cv.state IN ('waiting', 'offered', 'assigned')
    GROUP BY cv.company_id
    HAVING count(*) >= $1::bigint
    UNION
    SELECT cv.company_id FROM conversations AS cv
    WHERE cv.state = 'waiting' AND cv.team_queue
      AND NOT EXISTS (SELECT 1 FROM companies AS c WHERE c.company_id = cv.company_id AND c.team_active)
) AS t
CROSS JOIN LATERAL (
    SELECT count(*)::bigint AS n FROM conversations AS cv
    WHERE cv.company_id = t.company_id AND cv.state IN ('waiting', 'offered', 'assigned')
) AS l
ORDER BY l.n DESC, t.company_id
`

type TeamCompaniesRow struct {
	CompanyID  string
	ActiveLoad int64
}

// TeamCompanies lists the companies a team check looks at: those with an
// active team, those whose active load reaches the form threshold, and
// those with a waiting conversation in a team queue but no active team.
// The highest active load comes first, then the company ID, so when the
// team cap does not leave room for every company, the busiest one gets it
// (decision 0009, "A cap on the operators that teams hold").
func (q *Queries) TeamCompanies(ctx context.Context, formLoad int64) ([]TeamCompaniesRow, error) {
	rows, err := q.db.Query(ctx, teamCompanies, formLoad)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TeamCompaniesRow{}
	for rows.Next() {
		var i TeamCompaniesRow
		if err := rows.Scan(&i.CompanyID, &i.ActiveLoad); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const teamLock = `-- name: TeamLock :exec
SELECT pg_advisory_xact_lock($1::bigint)
`

// TeamLock serializes the team operations of all routers for the rest of
// the transaction. They are rare, and one at a time they cannot deadlock
// on each other's operators.
func (q *Queries) TeamLock(ctx context.Context, key int64) error {
	_, err := q.db.Exec(ctx, teamLock, key)
	return err
}

const teamMembers = `-- name: TeamMembers :many
SELECT
    o.id,
    COALESCE((SELECT array_agg(ol.lang ORDER BY ol.lang) FROM operator_languages AS ol
              WHERE ol.operator_id = o.id), '{}')::text[] AS languages,
    (SELECT count(*) FROM offers AS f
     WHERE f.operator_id = o.id AND f.state IN ('offered', 'accepted'))::integer AS live
FROM operators AS o
WHERE o.dedicated_company_id = $1::text
ORDER BY o.id
`

type TeamMembersRow struct {
	ID        string
	Languages []string
	Live      int32
}

// TeamMembers lists the members of a team with their languages and load.
func (q *Queries) TeamMembers(ctx context.Context, companyID string) ([]TeamMembersRow, error) {
	rows, err := q.db.Query(ctx, teamMembers, companyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TeamMembersRow{}
	for rows.Next() {
		var i TeamMembersRow
		if err := rows.Scan(&i.ID, &i.Languages, &i.Live); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const teamServesLang = `-- name: TeamServesLang :one
SELECT EXISTS (
    SELECT 1
    FROM companies AS c
    JOIN operators AS o ON o.dedicated_company_id = c.company_id
    JOIN operator_languages AS ol ON ol.operator_id = o.id AND ol.lang = $1
    WHERE c.company_id = $2 AND c.team_active
)::boolean AS serves
`

type TeamServesLangParams struct {
	Lang      string
	CompanyID string
}

// TeamServesLang reports whether the company has an active team with a
// member who has the language (decision 0009, "Languages in a team").
func (q *Queries) TeamServesLang(ctx context.Context, arg TeamServesLangParams) (bool, error) {
	row := q.db.QueryRow(ctx, teamServesLang, arg.Lang, arg.CompanyID)
	var serves bool
	err := row.Scan(&serves)
	return serves, err
}

const tryLockConversation = `-- name: TryLockConversation :one
SELECT company_id, customer_id, conv_session, conv_seq, lang, state, team_queue, priority, queued_at, preferred_operator_id, last_operator_id, route_seq, sla_started_at, first_accepted_at, first_replied_at, sla_assignment_missed, sla_response_missed, sim_response_us, real_response_us, close_reason, updated_at, last_offer_id FROM conversations
WHERE company_id = $1 AND customer_id = $2
FOR UPDATE SKIP LOCKED
`

type TryLockConversationParams struct {
	CompanyID  string
	CustomerID string
}

// TryLockConversation locks the conversation row, or returns no row when
// another transaction holds it. For the timer sweeps.
func (q *Queries) TryLockConversation(ctx context.Context, arg TryLockConversationParams) (Conversation, error) {
	row := q.db.QueryRow(ctx, tryLockConversation, arg.CompanyID, arg.CustomerID)
	var i Conversation
	err := row.Scan(
		&i.CompanyID,
		&i.CustomerID,
		&i.ConvSession,
		&i.ConvSeq,
		&i.Lang,
		&i.State,
		&i.TeamQueue,
		&i.Priority,
		&i.QueuedAt,
		&i.PreferredOperatorID,
		&i.LastOperatorID,
		&i.RouteSeq,
		&i.SlaStartedAt,
		&i.FirstAcceptedAt,
		&i.FirstRepliedAt,
		&i.SlaAssignmentMissed,
		&i.SlaResponseMissed,
		&i.SimResponseUs,
		&i.RealResponseUs,
		&i.CloseReason,
		&i.UpdatedAt,
		&i.LastOfferID,
	)
	return i, err
}

